import requests
import sys
import re

def evaluate_expression(expr, vars_dict):
    try:
        # Replace variables with their values
        for var, value in vars_dict.items():
            expr = expr.replace(f"{{{{{var}}}}}", str(value))
        # Evaluate the arithmetic expression
        return eval(expr, {'__builtins__': None}, {})
    except Exception:
        return None

def run_check(check):
    vars_dict = check["vars"]
    query = check["query"]
    db_path = check["db"]
    threshold = check["threshold"]
    webhook = check["webhook"]

    # Replace placeholders with evaluated expressions
    try:
