        for var in vars_dict:
            expr = vars_dict[var]
            cutoff_expr = f"{expr} + 3600"
            evaluated_query = evaluated_query.replace(f"{{{{{var}}}}}", str(evaluate_expression(expr, vars_dict)))
            evaluated_query = evaluated_query.replace(f"{{{{cutoff + 3600}}}}", str(evaluate_expression(cutoff_expr, vars_dict)))
    except Exception:
        return (check["name"], 0, "failed")

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute(evaluated_query)
    result = cursor.fetchone()
    conn.close()

    if not result:
        return (check["name"], 0, "failed")

