import json
import sqlite3
import requests
import re
from typing import List, Dict, Any

def evaluate_expression(expr: str) -> int:
    try:
        return int(eval(expr))
    except:
        raise ValueError(f"Invalid expression: {expr}")

def resolve_placeholders(query: str) -> str:
    def replace_match(match):
        expr = match.group(1)
        return str(evaluate_expression(expr))

    return re.sub(r'\{\{([^}]+)\}\}', replace_match, query)

def run_check(check: Dict[str, Any], db_path: str) -> int:
    resolved_query = resolve_placeholders(check["query"])
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute(resolved_query)
    result = cursor.fetchone()
    conn.close()
    if not result:
        raise ValueError(f"No results for query: {resolved_query}")
    return int(result[0])

def send_webhook(check: Dict[str, Any], value: int) -> str:
    try:
        response = requests.post(
            check["webhook"],
            json={"check": check["name"], "value": value},
            headers={"Content-Type": "application/json"}
        )
        return "sent" if response.status_code < 400 else "failed"
    except:
        return "failed"

def process_check(check: Dict[str, Any], db_path: str) -> None:
    try:
        value = run_check(check, db_path)
        if value > check["threshold"]:
            outcome = send_webhook(check, value)
        else:
            outcome = "skipped"
        print(f"{check['name']} {value} {outcome}")
    except Exception as e:
        print(f"{check['name']} {str(e)} failed")

def main():
    import sys
    if len(sys.argv) != 2:
        print("Usage: python alertcheck.py checks.json")
        return

    with open(sys.argv[1], "r") as f:
        data = json.load(f)

    checks = data["checks"]
