import json
import sqlite3
import requests
import sys
import re

def evaluate_expression(expr):
    # Evaluate the arithmetic expression safely
    return eval(expr)

def replace_placeholders(query):
    # Replace placeholders in the query with evaluated expressions
    def replacer(match):
        expression = match.group(1)
        return str(evaluate_expression(expression))
    return re.sub(r'{{(.*?)}}', replacer, query)

def main():
    if len(sys.argv) != 2:
        return
    checks_file = sys.argv[1]
    with open(checks_file) as f:
        data = json.load(f)
    checks = data['checks']

    for check in checks:
        name = check['name']
        db_path = check['db']
        query = check['query']
        threshold = check['threshold']
        webhook = check['webhook']

        # Replace placeholders in the query
        final_query = replace_placeholders(query)

        # Execute the query
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(final_query)
        result = cursor.fetchone()
        conn.close()

        if result:
            value = int(result[0])
        else:
            value = 0

        # Determine outcome
        if value > threshold:
            payload = {'check': name, 'value': value}
            try:
                response = requests.post(webhook, json=payload, headers={'Content-Type': 'application/json'})
                if response.status_code < 400:
                    outcome = 'sent'
                else:
                    outcome = 'failed'
            except Exception:
                outcome = 'failed'
        else:
            outcome = 'skipped'

        # Print the result
        print(f'{name} {value} {outcome}') 

if __name__ == '__main__':
    main()
